(()=>{'use strict';
const words={
 title:['前線決賽名單交接（TEST）','Frontline final roster handoff (TEST)','अग्रपङ्क्तिको फाइनल सूची हस्तान्तरण (परीक्षण)'],
 boundary:['隔離虛構演練。只登錄前線選定名單，不代表正式資格核准，不開放正式投票或收費。','Isolated fictional rehearsal. Records the frontline selection, not official eligibility or public voting/payment.','छुट्टै काल्पनिक अभ्यास। अग्रपङ्क्तिको छनोट अभिलेख मात्र; आधिकारिक योग्यता, मतदान वा भुक्तानी होइन।'],
 workflow:['前線自行評選 → 主辦核對名單 → 決賽重新評分；前幾關分數不累加。','Frontline selects → organizer checks roster → final starts with new grades. Earlier scores are not added.','अग्रपङ्क्तिले छान्छ → आयोजकले सूची जाँच्छ → फाइनलमा नयाँ अङ्क। पहिलेका अङ्क जोडिँदैनन्।'],
 back:['返回工作台','Staff workspace','कर्मचारी कार्यक्षेत्र'],source:['前線結果來源代號','Frontline result reference','अग्रपङ्क्तिको नतिजा सन्दर्भ'],sourceNote:['僅填內部文件代號，不填電話、Email、檔案網址或證件資料。','Internal reference only; no phone, email, document URL or identity information.','आन्तरिक सन्दर्भ मात्र; फोन, इमेल, कागजात URL वा परिचय विवरण नलेख्नुहोस्।'],
 previous:['上一頁','Previous','अघिल्लो'],next:['下一頁','Next','अर्को'],preview:['核對已選名單','Check selected roster','छानिएको सूची जाँच्नुहोस्'],review:['確認交接名單','Review handoff','हस्तान्तरण जाँच'],edit:['返回選人','Change selection','छनोट बदल्नुहोस्'],
 ack:['我已核對前線名單；本次僅確認虛構 TEST，不取代正式資格審核。','I checked the frontline list. This confirms fictional TEST only, not official eligibility.','मैले अग्रपङ्क्तिको सूची जाँचेँ। यो काल्पनिक परीक्षण पुष्टि मात्र हो, आधिकारिक योग्यता होइन।'],confirm:['確認並儲存交接','Confirm and save handoff','हस्तान्तरण पुष्टि र सुरक्षित गर्नुहोस्'],check:['查核儲存紀錄','Check saved record','सुरक्षित विवरण जाँच्नुहोस्'],receipt:['資料庫交接紀錄','Database handoff receipt','डाटाबेस हस्तान्तरण रसिद'],
 judge:['前往決賽評分演練','Final judging rehearsal','फाइनल मूल्याङ्कन अभ्यास'],vote:['前往決賽投票管理演練','Final ballot administration rehearsal','फाइनल मतदान व्यवस्थापन अभ्यास'],
 loading:['讀取中…','Loading…','लोड हुँदैछ…'],saving:['儲存中，請勿重複送出…','Saving; do not submit again…','सुरक्षित हुँदैछ; फेरि नपठाउनुहोस्…'],saved:['已由資料庫確認交接成功。','Handoff saved and confirmed by database.','डाटाबेसबाट हस्तान्तरण सुरक्षित भएको पुष्टि।'],unknown:['儲存結果尚未確認，請先查核紀錄。','Save outcome unknown. Check the record first.','सुरक्षित परिणाम अनिश्चित। पहिले विवरण जाँच्नुहोस्।'],retry:['尚未找到紀錄，可用原請求重試。','No record found yet. Retry the original request.','विवरण भेटिएन। मूल अनुरोध फेरि प्रयास गर्नुहोस्।'],failed:['無法完成，保留選擇；請重新核對或登入。','Unable to complete. Selection retained; check again or sign in.','पूरा भएन। छनोट राखिएको छ; फेरि जाँच्नुहोस् वा लगइन गर्नुहोस्।'],blocked:['名單未通過檢查，請返回修正。','Roster check blocked. Return and correct it.','सूची जाँच रोकियो। फर्केर सच्याउनुहोस्।'],ready:['核對通過，尚未儲存。','Check passed; not yet saved.','जाँच सफल; अझै सुरक्षित छैन।'],selected:['已選','Selected','छानिएका'],region:['地區','Area','क्षेत्र']};
const $=id=>document.getElementById(id),selected=new Set(),records=new Map();let language='zh',page=0,total=0,preview=null,pending=null,busy=false,status='',done=false;
const t=key=>words[key]?.[['zh','en','ne'].indexOf(language)]||key;
function message(key){status=key;$('handoff-status').textContent=t(key)}
function translate(){document.documentElement.lang={zh:'zh-Hant',en:'en',ne:'ne'}[language];document.querySelectorAll('[data-word]').forEach(e=>e.textContent=t(e.dataset.word));if(status)message(status);count();if(preview)$('handoff-summary').textContent=`${preview.manifest.source_reference} · ${preview.manifest.entries.length} / 10 · A ${preview.region_counts.A} / 5 · B ${preview.region_counts.B} / 5`}
function count(){$('handoff-count').textContent=`${t('selected')} ${selected.size} / 10`;$('handoff-page').textContent=`${page+1} / ${Math.max(1,Math.ceil(total/10))}`}
function controls(){for(const e of document.querySelectorAll('input,button'))e.disabled=busy||done||Boolean(pending);$('handoff-prev').disabled||=page===0;$('handoff-next').disabled||=(page+1)*10>=total;$('handoff-preview').disabled||=selected.size===0;$('handoff-confirm').disabled=busy||done||!preview||preview.blocked||!$('handoff-ack').checked||Boolean(pending);$('handoff-check').disabled=busy;$('handoff-retry').disabled=busy||done;}
async function api(body){const r=await fetch('/api/frontline-handoff-test',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const value=await r.json();if(!r.ok||value.ok!==true){const error=Error(value.error||'unavailable');error.status=r.status;throw error}return value}
async function perform(action){if(busy)return;busy=true;controls();try{await action()}catch{message('failed')}finally{busy=false;controls()}}
async function load(){message('loading');const data=await api({operation:'list',page});total=data.total;$('handoff-candidates').replaceChildren();for(const entry of data.entries){records.set(entry.application_id,entry);const label=document.createElement('label');label.className='row';const box=document.createElement('input');box.type='checkbox';box.value=entry.application_id;box.checked=selected.has(entry.application_id);box.onchange=()=>{if(box.checked){if(selected.size>=10){box.checked=false;return}selected.add(box.value)}else selected.delete(box.value);preview=null;count();controls()};const text=document.createElement('span');text.textContent=`${entry.stage_name} · ${entry.application_id} · ${entry.competition_region}`;label.append(box,text);$('handoff-candidates').append(label)}message('');count()}
function saved(receipt){if(!receipt?.id||receipt.member_count!==10)throw Error('readback_required');done=true;pending=null;$('handoff-picker').hidden=true;$('handoff-review').hidden=true;$('handoff-receipt').hidden=false;$('handoff-receipt-text').textContent=`${receipt.source_reference} · ${receipt.id} · ${receipt.member_count}`;message('saved')}
$('handoff-preview').onclick=()=>perform(async()=>{const source=$('handoff-source');if(!source.value||!source.checkValidity())return source.reportValidity();preview=await api({operation:'preview',application_ids:[...selected],source_reference:source.value});$('handoff-picker').hidden=true;$('handoff-review').hidden=false;$('handoff-ack').checked=false;$('handoff-blockers').replaceChildren();$('handoff-selected').replaceChildren();for(const entry of preview.manifest.entries){const p=document.createElement('p');p.textContent=`${preview.display_entries.find(row=>row.application_id===entry.application_id)?.stage_name||''} · ${entry.application_id} · ${entry.competition_region||'—'}`;$('handoff-selected').append(p)}for(const reason of preview.blocking_reasons){const p=document.createElement('p');p.textContent=[t('blocked'),reason.application_id,reason.competition_region].filter(Boolean).join(' · ');p.dataset.reason=reason.code;$('handoff-blockers').append(p)}translate();message(preview.blocked?'blocked':'ready')});
$('handoff-edit').onclick=()=>{preview=null;$('handoff-review').hidden=true;$('handoff-picker').hidden=false;controls()};
$('handoff-ack').onchange=controls;
function saveFailure(error){if(error.status>=400&&error.status<500){pending=null;preview=null;$('handoff-review').hidden=true;$('handoff-picker').hidden=false;$('handoff-check').hidden=true;$('handoff-retry').hidden=true;message('failed')}else{message('unknown');$('handoff-check').hidden=false}}
$('handoff-confirm').onclick=()=>perform(async()=>{pending={operation:'confirm',application_ids:[...selected],source_reference:preview.manifest.source_reference,preview_fingerprint:preview.fingerprint,version:preview.version,request_id:crypto.randomUUID(),acknowledge_test:true};message('saving');try{const result=await api(pending);saved(result.receipt)}catch(error){saveFailure(error)}});
$('handoff-check').onclick=()=>perform(async()=>{if(!pending)return;try{const result=await api({operation:'receipt',request_id:pending.request_id});if(result.receipt)saved(result.receipt);else{message('retry');$('handoff-retry').hidden=false}}catch{message('unknown')}});
$('handoff-retry').onclick=()=>perform(async()=>{if(!pending)return;message('saving');try{saved((await api(pending)).receipt)}catch(error){saveFailure(error)}});
for(const [id,delta]of[['handoff-prev',-1],['handoff-next',1]])$(id).onclick=()=>perform(async()=>{page+=delta;await load()});
$('handoff-language').onchange=()=>{language=$('handoff-language').value;translate()};translate();perform(async()=>{const current=await api({operation:'current'});if(current.receipt)saved(current.receipt);else await load()});
})();
